public static int countOilDeposits(char[][] grid) {
    int numDeposits = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                numDeposits++;
                // Mark all connected '@'s as visited
                markConnectedOilDeposits(grid, i, j);
            }
        }
    }
    return numDeposits;
}

private static void markConnectedOilDeposits(char[][] grid, int i, int j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[i].length || grid[i][j] != '@') {
        return;
    }
    grid[i][j] = '*';
    markConnectedOilDeposits(grid, i + 1, j);
    markConnectedOilDeposits(grid, i - 1, j);
    markConnectedOilDeposits(grid, i, j + 1);
    markConnectedOilDeposits(grid, i, j - 1);
}

