    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < edges.length; j++) {
            int u = edges[j][0];
            int v = edges[j][1];
            if (dist[u] != Integer.MAX_VALUE && dist[v] > dist[u] + 1) {
                dist[v] = dist[u] + 1;
            }
        }
    }

    int totalTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            totalTime += dist[i];
        }
    }

    return totalTime;
}

